import os

def get_mail_settings():
    mail_settings = {
        'MAIL_SERVER': os.environ.get('MAIL_SERVER', 'localhost')
    }

    # Handle MAIL_PORT with integer conversion and validation
    mail_port = os.environ.get('MAIL_PORT')
    if mail_port is None:
        mail_settings['MAIL_PORT'] = 25
    else:
        try:
            mail_settings['MAIL_PORT'] = int(mail_port)
        except ValueError:
            raise ValueError("MAIL_PORT should be integer.")

    # Handle MAIL_USE_TLS as boolean
    mail_use_tls = os.environ.get('MAIL_USE_TLS')
    mail_settings['MAIL_USE_TLS'] = mail_use_tls == 'True'

    mail_settings['MAIL_USERNAME'] = os.environ.get('MAIL_USERNAME')
    mail_settings['MAIL_PASSWORD'] = os.environ.get('MAIL_PASSWORD')

    return mail_settings

