import java.util.*;

class GraphAnalyzer {
    public static Map<String, Object> analyzeGraph(int[][] graph, int source) {
        int n = graph.length;
        int[] dist = new int[n];
        int[] prev = new int[n];
        Arrays.fill(dist, Integer.MAX_VALUE);
        Arrays.fill(prev, -1);
        dist[source] = 0;

        PriorityQueue<Vertex> pq = new PriorityQueue<>(Comparator.comparingInt(v -> v.distance));
        pq.offer(new Vertex(source, 0));

        while (!pq.isEmpty()) {
            Vertex current = pq.poll();
            int u = current.index;
            if (current.distance != dist[u]) continue;

            for (int v = 0; v < n; v++) {
                if (graph[u][v] != 0) {
                    int alt = dist[u] + graph[u][v];
                    if (alt < dist[v]) {
                        dist[v] = alt;
                        prev[v] = u;
                        pq.offer(new Vertex(v, alt));
                    }
                }
            }
        }

        List<List<Integer>> paths = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            paths.add(buildPath(prev, source, i));
        }

        Map<String, Object> result = new HashMap<>();
        result.put("distances", dist);
        result.put("paths", paths);
        return result;
    }

    private static List<Integer> buildPath(int[] prev, int source, int target) {
        LinkedList<Integer> path = new LinkedList<>();
        if (prev[target] == -1 && target != source) {
            return path;
        }
        for (int at = target; at != -1; at = prev[at]) {
            path.addFirst(at);
        }
        return path;
    }

    private static class Vertex {
        int index;
        int distance;

        Vertex(int index, int distance) {
            this.index = index;
            this.distance = distance;
        }
    }
}

