import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;

/**
 * Basic course scheduler that builds a directed graph from the prerequisite
 * list, computes indegrees and performs a Kahn‑style topological sort.
 *
 * If a complete ordering covering all courses can be produced, {@code canFinish}
 * is {@code true}; otherwise (i.e., a cycle exists) it is {@code false} and the
 * returned order may be incomplete.
 */
public class CourseScheduler {

    /** Result of the scheduling operation. */
    public static class Result {
        /** true if all courses can be completed (i.e., a full topological order exists). */
        public final boolean canFinish;
        /** A possible ordering of courses; may be empty or partial when canFinish is false. */
        public final int[] order;

        public Result(boolean canFinish, int[] order) {
            this.canFinish = canFinish;
            this.order = order;
        }
    }

    /**
     * Determines whether all courses can be finished and provides a valid ordering.
     *
     * @param numCourses    total number of courses labeled from 0 to numCourses‑1
     * @param prerequisites a 2‑D array where each element {@code [a, b]} means
     *                      course {@code a} depends on course {@code b}
     * @return a {@link Result} containing the feasibility flag and a possible order
     */
    public Result scheduleCourses(int numCourses, int[][] prerequisites) {
        // Build adjacency list and indegree array
        List<List<Integer>> graph = new ArrayList<>(numCourses);
        for (int i = 0; i < numCourses; i++) {
            graph.add(new ArrayList<>());
        }
        int[] indegree = new int[numCourses];

        for (int[] edge : prerequisites) {
            int dest = edge[0]; // course that depends on src
            int src = edge[1];  // prerequisite course
            graph.get(src).add(dest);
            indegree[dest]++;   // incoming edge to dest
        }

        // Queue of courses with no prerequisites (indegree == 0)
        Queue<Integer> queue = new ArrayDeque<>();
        for (int i = 0; i < numCourses; i++) {
            if (indegree[i] == 0) {
                queue.offer(i);
            }
        }

        // Perform Kahn's algorithm
        int[] order = new int[numCourses];
        int idx = 0;
        while (!queue.isEmpty()) {
            int cur = queue.poll();
            order[idx++] = cur;

            for (int neighbor : graph.get(cur)) {
                indegree[neighbor]--;
                if (indegree[neighbor] == 0) {
                    queue.offer(neighbor);
                }
            }
        }

        // If we processed all courses, there is no cycle.
        boolean canFinish = idx == numCourses;
        // If a cycle exists, truncate the order to the processed part.
        if (!canFinish) {
            int[] partial = new int[idx];
            System.arraycopy(order, 0, partial, 0, idx);
            order = partial;
        }

        return new Result(canFinish, order);
    }

    // Optional simple test harness
    public static void main(String[] args) {
        CourseScheduler scheduler = new CourseScheduler();

        // Example 1: no cycle
        int numCourses1 = 5;
        int[][] prereq1 = { {1, 0}, {2, 0}, {3, 1}, {4, 2} };
        Result r1 = scheduler.scheduleCourses(numCourses1, prereq1);
        System.out.println("Can finish: " + r1.canFinish);
        System.out.print("Order: ");
        for (int c : r1.order) System.out.print(c + " ");
        System.out.println();

        // Example 2: cycle exists (0->1, 1->2, 2->0)
        int numCourses2 = 3;
        int[][] prereq2 = { {1, 0}, {2, 1}, {0, 2} };
        Result r2 = scheduler.scheduleCourses(numCourses2, prereq2);
        System.out.println("Can finish: " + r2.canFinish);
        System.out.print("Order: ");
        for (int c : r2.order) System.out.print(c + " ");
        System.out.println();
    }
}

