        }
        int[] indegree = new int[numCourses];

        for (int[] edge : prerequisites) {
            int dest = edge[0]; // course that depends on src
            int src = edge[1];  // prerequisite course
            graph.get(src).add(dest);
            indegree[dest]++;   // incoming edge to dest
        }

        // ---------- 2. Initialise queue with zero‑indegree vertices ----------
