        this.pollingCount = new AtomicInteger(0);
        this.maxPollingAttempts = maxPollingAttempts;
    }

    public synchronized void enqueue(T element) {
        queue.add(element);
        notifyAll();
    }

    public synchronized T poll() {
        if (pollingCount.get() >= maxPollingAttempts) {
            throw new IllegalStateException("Max polling attempts exceeded");
        }
        T element = queue.poll();
        if (element != null) {
            pollingCount.incrementAndGet();
        }
        return element;
    }

    public synchronized T waitForElement(long timeoutMillis) throws InterruptedException {
        if (pollingCount.get() >= maxPollingAttempts) {
            throw new IllegalStateException("Max polling attempts exceeded");
        }

        long startTime = System.currentTimeMillis();
        long remainingTime = timeoutMillis;

        while (queue.isEmpty()) {
            if (remainingTime <= 0) {
                return null;
            }
            wait(remainingTime);
            remainingTime = timeoutMillis - (System.currentTimeMillis() - startTime);
        }

        T element = queue.poll();
        if (element != null) {
            pollingCount.incrementAndGet();
        }
        return element;
    }

    public synchronized void resetPollingCount() {
        pollingCount.set(0);
    }

    public synchronized int getPollingCount() {
        return pollingCount.get();
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;

        PollingQueue<?> that = (PollingQueue<?>) o;

        if (maxPollingAttempts != that.maxPollingAttempts) return false;
        if (pollingCount.get() != that.pollingCount.get()) return false;
        return queue.equals(that.queue);
    }

    @Override
    public int hashCode() {
        int result = queue.hashCode();
        result = 31 * result + pollingCount.get();
        result = 31 * result + maxPollingAttempts;
        return result;
    }
}

