    public int getWordFrequency(String word) {
        if (word == null || word.isEmpty()) {
            return 0;
        }

        TrieNode current = root;

        // Traverse through each character in the word
        for (int i = 0; i < word.length(); i++) {
            char c = word.charAt(i);

            // Find the child with this character using binary search
            TrieNode child = null;
            int left = 0, right = current.childCount - 1;

            while (left <= right) {
                int mid = left + (right - left) / 2;
                if (current.children[mid] != null && current.children[mid].data == c) {
                    child = current.children[mid];
                    break;
                } else if (current.children[mid].data < c) {
                    left = mid + 1;
                } else {
                    right = mid - 1;
                }
            }

            // If child doesn't exist, the word is not in the trie
            if (child == null) {
                return 0;
            }

            // Move to the child node
            current = child;
        }

        // Return the frequency if it's the end of a word, otherwise 0
        return current.isEndOfWord ? current.getFrequency() : 0;
