            return words;
        }

        // Handle empty prefix - return all words
        if (prefix.isEmpty()) {
            return getAllWords();
        }

        // Find the node at the end of the prefix
        TrieNode current = root;
        for (int i = 0; i < prefix.length(); i++) {
            char c = prefix.charAt(i);

            // Find the child with this character using binary search
            TrieNode child = null;
            int left = 0, right = current.childCount - 1;

