def iterate_flattened_separately(dictionary, manually_sorted_keys=None):
    """
    Recursively iterate over all items in a nested dictionary and yield each key-value pair.

    This function traverses a nested dictionary structure and yields each key-value
    pair with the key represented as a dotted path string. The iteration order
    can be customized by providing a list of manually sorted keys.

    Parameters
    ----------
    dictionary : dict
        The nested dictionary to iterate over.
    manually_sorted_keys : list, optional
        A list of keys that should be yielded first, in the specified order.
        If None, all keys are yielded in natural sort order.

    Yields
    ------
    tuple
        A tuple (dotted_path, value) for each leaf node in the dictionary.

    Examples
    --------
    >>> d = {'a': 1, 'b': {'c': 2, 'd': 3}}
    >>> list(iterate_flattened_separately(d))
    [('a', 1), ('b.c', 2), ('b.d', 3)]

    >>> list(iterate_flattened_separately(d, manually_sorted_keys=['b']))
    [('b.c', 2), ('b.d', 3), ('a', 1)]
    """
    def _flatten_dict(d, parent_key=''):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(_flatten_dict(v, new_key))
            else:
                items.append((new_key, v))
        return items

    if manually_sorted_keys is None:
        manually_sorted_keys = []

    # Create a set for faster lookup
    manual_keys_set = set(manually_sorted_keys)

    # First yield manually sorted keys and their nested children
    for key in manually_sorted_keys:
        if key in dictionary:
            value = dictionary[key]
            if isinstance(value, dict):
                for path, val in _flatten_dict(value, key):
                    yield (path, val)
            else:
                yield (key, value)

    # Then yield remaining keys and their nested children in sorted order
    for key in sorted(dictionary.keys()):
        if key not in manual_keys_set:
            value = dictionary[key]
            if isinstance(value, dict):
                for path, val in _flatten_dict(value, key):
                    yield (path, val)
            else:
                yield (key, value)

def _tokenize_line(line: str) -> List[_PrettyToken]:
    """
    Tokenize a line of text into a list of tokens, each representing a distinct part of the line.
    Ensure that the tokenizer separates the main body of the line from any trailing whitespace or newline characters, assigning each to distinct tokens.
    """
    tokens = []

    # Separate the line content from trailing whitespace
    content_end = len(line.rstrip('\r\n'))
    content = line[:content_end]
    trailing_newline = line[content_end:]

    # Tokenize the content part
    if content:
        tokens.extend(_tokenize_str(content))
    else:
        tokens.append(_PrettyToken(_PrettyTokenType.BODY, ""))

    # Add trailing newline characters as separate tokens
    for char in trailing_newline:
        if char in '\r\n':
            tokens.append(_PrettyToken(_PrettyTokenType.NEWLINE, char))

    return _optimize_tokens(tokens)

