    def idle_check(self, timeout=None):
        """Check for any IDLE responses sent by the server.

        This method should only be called when the server is in IDLE
        mode (see ``idle()``).

        Blocks until a response is received or the optional *timeout*
        is reached. *timeout* is in seconds.

        Returns a list of responses received. The list may be empty if
        the timeout was reached. Responses are returned as tuples of
        the form ``(data, response_type)`` where *data* is the raw
        bytes received and *response_type* is the type of response
        (e.g. ``b'EXISTS'``, ``b'EXPUNGE'``, etc.).
        """
        if self._idle_tag is None:
            raise exceptions.IMAPClientError("Server not in IDLE mode")

        sock = self.socket()

        # Use poll() if available, otherwise fall back to select()
        if POLL_SUPPORT:
            poll_func = self._poll_socket
        else:
            poll_func = self._select_poll_socket

        # Check if data is available to read
        if not poll_func(sock, timeout):
            return []

        # Read the available responses
        responses = []
        try:
            while True:
                # Non-blocking check for response
                try:
                    resp = self._imap._get_response()
                    if resp is not None:
                        responses.append(resp)
                    else:
                        break
                except (socket.timeout, socket.error):
                    break
        except Exception:
            # If there's an error, stop IDLE mode
            self.idle_done()
            raise

        return responses

