    if depth < 0:
        return []

    if depth == 0:
        results = set()

        # Only include the most standard harmonic substitutions
        # I ↔ VI (tonic substitution - very common)
        # IV ↔ II (subdominant substitution - very common)
        # V ↔ VII (dominant substitution - very common)
        # These are the core functional substitutions in classical harmony

        # Get the chord to substitute
        chord = progression[substitute_index]
        (roman, acc, suff) = parse_string(chord)

        # I ↔ VI substitution (tonic substitution)
        if roman == "I" or roman == "VI":
            if roman == "I":
                results.add(tuple_to_string(("VI", acc, suff)))
            else:  # roman == "VI"
                results.add(tuple_to_string(("I", acc, suff)))

        # IV ↔ II substitution (subdominant substitution)
        if roman == "IV" or roman == "II":
            if roman == "IV":
                results.add(tuple_to_string(("II", acc, suff)))
            else:  # roman == "II"
                results.add(tuple_to_string(("IV", acc, suff)))

        # V ↔ VII substitution (dominant substitution)
        if roman == "V" or roman == "VII":
            if roman == "V":
                results.add(tuple_to_string(("VII", acc, suff)))
            else:  # roman == "VII"
                results.add(tuple_to_string(("V", acc, suff)))

        # Relative major/minor substitution
        # I ↔ VI (same as above but with different suffixes)
        # IV ↔ II (same as above but with different suffixes)
        if suff == "m" or suff == "m7":
            # Minor to major (relative major)
            if roman in ["II", "III", "VI"]:
                n = skip(roman, 2)
                a = interval_diff(roman, n, 3) + acc
                if suff == "m":
                    results.add(tuple_to_string((n, a, "M")))
                else:  # suff == "m7"
                    results.add(tuple_to_string((n, a, "M7")))
        elif suff == "M" or suff == "M7" or suff == "":
            # Major to minor (relative minor)
            if roman in ["I", "IV", "V"]:
                n = skip(roman, 5)
                a = interval_diff(roman, n, 9) + acc
                if suff == "M":
                    results.add(tuple_to_string((n, a, "m")))
                elif suff == "M7":
                    results.add(tuple_to_string((n, a, "m7")))
                else:  # suff == ""
                    results.add(tuple_to_string((n, a, "")))

        # Diminished to dominant substitution (very common)
        if roman == "VII" and (suff == "dim" or suff == "dim7" or suff == ""):
            # vii° often substitutes for V
            results.add(tuple_to_string(("V", acc, "dom7")))

        return list(results)

    else:
        immediate_subs = substitute(progression, substitute_index, 0)
        all_subs = set()
        for sub in immediate_subs:
            # Create new progression with the substituted chord
            new_progression = progression[:substitute_index] + [sub] + progression[substitute_index+1:]
            # Recursively get deeper substitutions
            deeper_subs = substitute(new_progression, substitute_index, depth-1)
            all_subs.update(deeper_subs)
        return list(all_subs)

def is_seventh_chord(suffix):
    # Seventh chords have suffixes that contain '7'
    return '7' in suffix or suffix in ['9', 'm9', 'M9', 'dim9', 'dom9']

else:
    immediate_subs = substitute(progression, substitute_index, 0)
    all_subs = set()
    for sub in immediate_subs:
        # Create new progression with the substituted chord
        new_progression = progression[:substitute_index] + [sub] + progression[substitute_index+1:]
        # Recursively get deeper substitutions
        deeper_subs = substitute(new_progression, substitute_index, depth-1)
        all_subs.update(deeper_subs)
    return list(all_subs)

