public String summarize() {
    if (matches == null) {
        return constraintName() + ": score=" + score + " (weight=" + weight + "), constraint match analysis not available.";
    }
    int totalMatches = matchCount;
    String constraintName = constraintName();

    if (totalMatches == 0) {
        return constraintName + ": score=" + score + " (weight=" + weight + "), 0 matches.";
    }

    List<MatchAnalysis<Score_>> sortedMatches = matches.stream()
        .sorted(Comparator.comparing(MatchAnalysis::score))
        .toList();

    StringBuilder sb = new StringBuilder();
    sb.append(constraintName).append(": score=").append(score).append(" (weight=").append(weight).append("), ").append(totalMatches).append(" matches:\n");

    int limit = Math.min(sortedMatches.size(), DEFAULT_SUMMARY_CONSTRAINT_MATCH_LIMIT);
    for (int i = 0; i < limit; i++) {
