        sb.append("  - score=").append(match.score()).append(", justification=").append(match.justification()).append("\n");
    }

    if (sortedMatches.size() > limit) {
        sb.append("  ... and ").append(sortedMatches.size() - limit).append(" more matches.");
    }

    return sb.toString();
}

