public String summarize() {
    if (matches == null) {
        throw new IllegalArgumentException("Constraint matches are null. Use ScoreAnalysisFetchPolicy.FETCH_ALL to obtain constraint matches.");
    }

    String constraintName = constraintName();
    int totalMatches = matches.size();

    if (totalMatches == 0) {
        return constraintName + ": score=" + score + " (weight=" + weight + "), 0 matches.";
    }

    List<MatchAnalysis<Score_>> sortedMatches = matches.stream()
        .sorted(Comparator.comparing(MatchAnalysis::score))
        .toList();

    StringBuilder sb = new StringBuilder();
    sb.append(constraintName).append(": score=").append(score).append(" (weight=").append(weight).append("), ").append(totalMatches).append(" matches:\n");

    int limit = Math.min(sortedMatches.size(), 5);
    for (int i = 0; i < limit; i++) {
        MatchAnalysis<Score_> match = sortedMatches.get(i);
        sb.append("  - score=").append(match.score()).append(", justification=").append(match.justification()).append("\n");
    }

    if (sortedMatches.size() > limit) {
        sb.append("  ... and ").append(sortedMatches.size() - limit).append(" more matches.");
    }

    return sb.toString();
}

