/**
 * Computes the cosine similarity between two {@link Embedding} objects.
 *
 * <p>The method performs the following steps:
 * <ul>
 *   <li>Null checks for both embeddings.</li>
 *   <li>Ensures the underlying vectors have the same length.</li>
 *   <li>Computes the dot product and the squared norms of both vectors in a single loop.</li>
 *   <li>Handles zero vectors by returning {@code 0.0} (treated as orthogonal).</li>
 *   <li>Calculates the cosine similarity as {@code dot / (normA * normB)}.</li>
 * </ul>
 *
 * @param embeddingA the first embedding
 * @param embeddingB the second embedding
 * @return the cosine similarity between the two embeddings
 * @throws IllegalArgumentException if either embedding is {@code null} or if the vector
 *                                  lengths differ
 */
public static double between(Embedding embeddingA, Embedding embeddingB) {
    // Null checks
    ensureNotNull(embeddingA, "one of the embedding is null.");
    ensureNotNull(embeddingB, "one of the embedding is null.");

    double[] vecA = embeddingA.getVector();
    double[] vecB = embeddingB.getVector();

    // Length check
    if (vecA.length != vecB.length) {
        throw new IllegalArgumentException(
                "the vector lengths of the two embeddings should be equal.");
    }

    // Compute dot product and squared norms in a single loop
    double dot = 0.0;
    double normSqA = 0.0;
    double normSqB = 0.0;
    for (int i = 0; i < vecA.length; i++) {
        double a = vecA[i];
        double b = vecB[i];
        dot += a * b;
        normSqA += a * a;
        normSqB += b * b;
    }

    double normA = Math.sqrt(normSqA);
    double normB = Math.sqrt(normSqB);

    // Handle zero vectors (orthogonal to all vectors, including themselves)
    final double EPSILON = 1e-12;
    if (normA < EPSILON || normB < EPSILON) {
        return 0.0;
    }

    // Compute cosine similarity
    return dot / (normA * normB);
}

/**
 * Helper method that throws an {@link IllegalArgumentException} if the provided object is {@code null}.
 *
 * @param obj     the object to check for nullity
 * @param message the exception message to use if {@code obj} is {@code null}
 */
private static void ensureNotNull(Object obj, String message) {
    if (obj == null) {
        throw new IllegalArgumentException(message);
    }
}

