PostgresMlEmbeddingOptions mergeOptions(EmbeddingOptions requestOptions) {
    if (requestOptions == null) {
        return defaultOptions;
    }

    if (!(requestOptions instanceof PostgresMlEmbeddingOptions)) {
        throw new IllegalArgumentException("requestOptions must be an instance of PostgresMlEmbeddingOptions");
    }

    PostgresMlEmbeddingOptions requestPostgresOptions = (PostgresMlEmbeddingOptions) requestOptions;

    String transformer = requestPostgresOptions.getTransformer() != null ? 
        requestPostgresOptions.getTransformer() : defaultOptions.getTransformer();
    VectorType vectorType = requestPostgresOptions.getVectorType() != null ? 
        requestPostgresOptions.getVectorType() : defaultOptions.getVectorType();
    Map<String, Object> kwargs = requestPostgresOptions.getKwargs() != null ? 
        requestPostgresOptions.getKwargs() : defaultOptions.getKwargs();
    MetadataMode metadataMode = requestPostgresOptions.getMetadataMode() != null ? 
        requestPostgresOptions.getMetadataMode() : defaultOptions.getMetadataMode();

    return PostgresMlEmbeddingOptions.builder()
        .transformer(transformer)
        .vectorType(vectorType)
        .kwargs(kwargs)
        .metadataMode(metadataMode)
        .build();
}

