private void encodeAnisotropic(VectorFloat<?> vector, ByteSequence<?> result) {
    int offset = 0;
    for (int m = 0; m < M; m++) {
        int[] subvectorSizeAndOffset = subvectorSizesAndOffsets[m];
        int subvectorSize = subvectorSizeAndOffset[0];
        int subvectorOffset = subvectorSizeAndOffset[1];

        VectorFloat<?> subvector = vector.subvector(subvectorOffset, subvectorSize);
        VectorFloat<?> codebook = codebooks[m];

        int bestIndex = 0;
        float bestDistance = Float.MAX_VALUE;

        for (int i = 0; i < clusterCount; i++) {
            VectorFloat<?> centroid = codebook.subvector(i * subvectorSize, subvectorSize);
            float distance = VectorUtil.distance(subvector, centroid, anisotropicThreshold);
            if (distance < bestDistance) {
                bestDistance = distance;
                bestIndex = i;
            }
        }

        result.setByte(offset, (byte) bestIndex);
        offset += 1;
    }
}

