            if (BEAN_MERGE_FIELD_EXCISIONS.contains(propertyName)) {
                continue;
            }
            if (sourceWrapper.isReadableProperty(propertyName) && targetWrapper.isWritableProperty(propertyName)) {
                Object sourceValue = sourceWrapper.getPropertyValue(propertyName);
                if (sourceValue != null) {
                    Object targetValue = targetWrapper.getPropertyValue(propertyName);
                    if (overrideNonNullTargetValues || targetValue == null) {
                        targetWrapper.setPropertyValue(propertyName, sourceValue);
                    }
                }
            }
        }

        return target;
    }
}

