public @NonNull String summarize() {
    StringBuilder sb = new StringBuilder();
    sb.append("Total score: ").append(score.toString()).append("\n\n");

    for (ConstraintAnalysis<Score_> analysis : constraintAnalyses()) {
        ConstraintRef ref = analysis.constraintRef();
        sb.append("Constraint: ").append(ref.constraintName())
          .append(" (score: ").append(analysis.score().toString()).append(")\n");

        var matches = analysis.matches();
        if (matches != null && !matches.isEmpty()) {
            int limit = Math.min(matches.size(), DEFAULT_SUMMARY_CONSTRAINT_MATCH_LIMIT);
            for (int i = 0; i < limit; i++) {
                var match = matches.get(i);
                sb.append("  Match ").append(i + 1)
                  .append(": score=").append(match.score().toString())
                  .append(", justification: ").append(match.justification().toString())
                  .append("\n");
            }
            if (matches.size() > DEFAULT_SUMMARY_CONSTRAINT_MATCH_LIMIT) {
                sb.append("  ... (and ").append(matches.size() - DEFAULT_SUMMARY_CONSTRAINT_MATCH_LIMIT)
                  .append(" more)\n");
            }
        }
        sb.append("\n");
    }

    return sb.toString();
}

